package br.com.conectatea.progresso.domain; import br.com.conectatea.meta.domain.StatusMeta; import jakarta.persistence.*; import java.time.Instant; @Entity @Table(name="progressos") public class Progresso { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="meta_id") private Long metaId; @Column(name="profissional_id") private Long profissionalId; @Column(name="progresso_anterior") private int progressoAnterior; @Column(name="progresso_atual") private int progressoAtual; @Enumerated(EnumType.STRING) private StatusMeta status; @Column(columnDefinition="text") private String descricao; private Instant data=Instant.now(); protected Progresso(){} public Progresso(Long m,Long p,int before,int after,StatusMeta s,String d){metaId=m;profissionalId=p;progressoAnterior=before;progressoAtual=after;status=s;descricao=d;} }
